Combinations.code:
void bt(int start, vector<int>& path) {
    if ((int)path.size() == k) {
        res.push_back(path); return;
    }
    int need = k - path.size();
    for (int i = start; i <= n - need + 1; i++) {
        path.push_back(i);
        bt(i + 1, path);
        path.pop_back();
    }
}

Remove Duplicates from Sorted List.code:
ListNode* cur = head;
while (cur && cur->next) {
    if (cur->next->val == cur->val)
        cur->next = cur->next->next;  // splice out
    else
        cur = cur->next;              // advance
}
return head;

Subsets II.code:
void bt(int start, vector<int>& path) {
    res.push_back(path);
    for (int i = start; i < n; i++) {
        if (i > start && nums[i] == nums[i-1])
            continue;      // dup at same level
        path.push_back(nums[i]);
        bt(i + 1, path);
        path.pop_back();
    }
}
